const PY_OPT = { toneType: 'symbol', toneSandhi: true };
const isDigits = seg => /^[零一二三四五六七八九]+$/.test(seg);   // 念號碼：一不變調
/* ── GoodTeacher 讀音規則（多音字、一／不、輕聲…）──
   標準：教育部國語辭典，多音字以 GoodTeacher 規則為準（game-kit/bank/gt）。
   做法：先用 pinyin-pro 算，再套 GoodTeacher「要改」的規則；一、不 兩個字則完全照規則（含「不改」）。
   下面這塊資料由 tools/build_gt_rules.js 產生，GoodTeacher 更新後重跑即可，所有遊戲一起更新。 */
